// Creating a custom Promise
const orderFood = new Promise((resolve, reject) => {
  console.log("Cooking food...");
  const success = true;

  setTimeout(() => {
    if (success) {
      resolve("🍔 Here is your burger!");
    } else {
      reject("❌ Sorry, we ran out of meat.");
    }
  }, 2000);
});

// Using the Promise
orderFood
  .then((food) => {
    console.log(food);
    return "Eating..."; // This passes to the next .then()
  })
  .then((action) => {
    console.log(action);
  })
  .catch((error) => {
    console.error(error);
  });

console.log("Chatting with friends while waiting...");
